package com.fooddelivery.delivery.repository; import com.fooddelivery.delivery.entity.Delivery; import java.util.List; import java.util.Optional; import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import jakarta.persistence.LockModeType; public interface DeliveryRepository extends JpaRepository<Delivery,Long>{List<Delivery> findByDriverIdIsNullAndStatusOrderByUpdatedAtAsc(String status);List<Delivery> findByDriverIdOrderByUpdatedAtDesc(Long id);Optional<Delivery> findByOrderIdAndDriverId(Long orderId,Long driverId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select d from Delivery d where d.driverId is null and d.status='READY' order by d.updatedAt asc")List<Delivery> findReadyForUpdate();}
